const fs=require('fs');
const input = $json;
let precomputedImage = null;
if (input.image_provider === 'precomputed') {
  try { precomputedImage = JSON.parse(input.image_model); } catch (error) { throw new Error('Replay de imagem invalido: image_model deve conter JSON.'); }
  if (!precomputedImage?.source_path || !precomputedImage?.model) throw new Error('Replay de imagem incompleto: source_path e model sao obrigatorios.');
}
const structured = input.structured_output || {};
const productCandidates = [structured.intent?.product, input.briefing?.product, input.request?.product, structured.briefing?.product];
const product = productCandidates.map(v => typeof v === 'string' ? v.trim() : '').find(Boolean) || '';
const objectiveCandidates = [structured.intent?.objective, input.briefing?.objective, structured.briefing?.objective, input.visual_description, structured.content?.visual_description];
const objective = objectiveCandidates.map(v => typeof v === 'string' ? v.trim() : '').find(Boolean) || '';
const genericProduct = /^(produto|item|comida|alimento|algo|nao informado|não informado|indefinido|desconhecido)$/i.test(product);
const subject = product && !genericProduct ? product : objective;
if (!subject) return [{json:{...input,product:null,needs_clarification:true,clarification_reason:'Assunto ou objetivo ausente no Structured Output e briefing. A geracao foi interrompida sem chamar o provider.'}}];
const safeClient = String(input.client_id).replace(/[^a-zA-Z0-9_-]/g, '-');
const safeContent = String(input.content_id).replace(/[^a-zA-Z0-9_-]/g, '-');
const relativePath = input.existing_operation_path || ('assets/generated/' + safeClient + '/' + safeContent + '/source/image-v' + Number(input.version||1) + '.png');
const containerPath = '/data/' + relativePath;
const outputDirectory = '/data/assets/generated/' + safeClient + '/' + safeContent + '/source';
const existingFile=fs.existsSync(containerPath)&&fs.statSync(containerPath).size>0;
const imageExists=input.existing_operation_status==='SUCCESS'&&existingFile;
if(input.existing_operation_status==='IN_PROGRESS'&&!existingFile)throw new Error('Geracao de imagem anterior permanece IN_PROGRESS; reconciliar antes de nova chamada para evitar cobranca duplicada.');
const primary = Array.isArray(input.primary_colors) ? input.primary_colors : [];
const secondary = Array.isArray(input.secondary_colors) ? input.secondary_colors : [];
const rules = Array.isArray(input.brand_rules) ? input.brand_rules : [];
const imagePrompt = input.image_prompt || structured.content?.image_prompt || '';
const visualDescription = input.visual_description || structured.content?.visual_description || '';
const prompt = [
  'Use case: ads-marketing',
  'Asset type: elemento visual para composicao posterior de social media',
  'Subject from persisted Structured Output: ' + subject,
  'Persisted image prompt: ' + imagePrompt,
  'Persisted briefing: ' + JSON.stringify(input.briefing || structured.briefing || {}),
  'Persisted visual description: ' + visualDescription,
  'Subject: representar fielmente o assunto solicitado (' + subject + ') sem introduzir temas externos',
  'Style/medium: visual publicitario profissional, realista ou ilustrativo conforme o briefing, premium e coerente com o segmento da marca',
  'Composition/framing: enquadramento quadrado, assunto nitido e espaco negativo limpo para composicao grafica posterior',
  'Brand profile: ' + [input.brand_name, input.business_type].filter(Boolean).join(' — '),
  'Official palette for atmosphere, surfaces and subtle props only: ' + [...primary, ...secondary].join(', '),
  'Brand rules: ' + rules.join('; '),
  'Constraints: gerar somente o elemento visual de fundo; nenhum layout de post; nao inserir nem redesenhar logo; sem nome da marca, texto, letras, numeros, telefone, endereco, preco, promocao, CTA, hashtags, molduras ou marca d agua; nao inventar caracteristicas nao presentes no briefing'
].join('\n');
const model = precomputedImage?.model || input.image_model || 'gpt-image-2';
return [{json:{...input,image_model:model,precomputed_source_path:precomputedImage?.source_path||null,precomputed_request_id:precomputedImage?.request_id||null,product:product||null,subject,needs_clarification:false,image_exists:imageExists,prompt,relative_path:relativePath,container_path:containerPath,output_directory:outputDirectory,width:Number(precomputedImage?.width||(input.image_provider === 'mock' ? 1 : 1024)),height:Number(precomputedImage?.height||(input.image_provider === 'mock' ? 1 : 1024)),quality:'low',idempotency_key:'image:'+input.version_id,openai_image_request:{model,prompt,size:'1024x1024',quality:'low',n:1,output_format:'png',background:'opaque',moderation:'auto'}}}];

