WITH content_updated AS (
  UPDATE social_media.content_items SET status = 'NEEDS_CLARIFICATION', updated_at = now() WHERE content_id = $1 RETURNING content_id, client_id, source_message_id
), event_created AS (
  INSERT INTO social_media.events (correlation_id, client_id, content_id, event_type, workflow_name, details)
  SELECT COALESCE(m.correlation_id, gen_random_uuid()), c.client_id, c.content_id, 'PRODUCT_CLARIFICATION_REQUIRED', '04 - Geracao de Imagem de Produto', jsonb_build_object('reason', $2, 'provider_called', false)
  FROM content_updated c LEFT JOIN social_media.messages m ON m.message_id = c.source_message_id RETURNING event_id
)
SELECT $1::text AS content_id, $2::text AS clarification_reason, (SELECT event_id FROM event_created LIMIT 1) AS event_id, false AS persisted_image, false AS provider_called;

