const fs=require('fs');
const context = $('Preparar Geracao Dinamica').first().json;
let png = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=';
let requestId='mock-' + Date.now();
if (context.image_provider === 'precomputed') {
  const source='/data/' + String(context.precomputed_source_path||'').replace(/^\/+/, '');
  if (!fs.existsSync(source) || fs.statSync(source).size===0) throw new Error('Imagem precomputada nao encontrada em ' + source);
  png=fs.readFileSync(source).toString('base64');
  requestId=context.precomputed_request_id||('precomputed-' + Date.now());
}
return [{json:{body:{created:Math.floor(Date.now()/1000),data:[{b64_json:png}],usage:{input_tokens:0,output_tokens:0,total_tokens:0,input_tokens_details:{text_tokens:0,image_tokens:0}}},headers:{'x-request-id':requestId},statusCode:200,image_provider:context.image_provider}}];

const fs = require('fs');
const response = $json;
const context = $('Preparar Geracao Dinamica').first().json;
const api = response.body || response;
const base64 = api.data?.[0]?.b64_json;
if (!base64) throw new Error('Image API nao retornou b64_json.');
fs.mkdirSync(context.output_directory, { recursive: true });
const usage = api.usage || {};
const details = usage.input_tokens_details || {};
const textInput = Number(details.text_tokens ?? usage.input_tokens ?? 0);
const imageInput = Number(details.image_tokens ?? 0);
const outputTokens = Number(usage.output_tokens ?? (context.image_provider === 'openai' ? 196 : 0));
const cost = context.image_provider === 'openai' ? (textInput * 5 + imageInput * 8 + outputTokens * 30) / 1000000 : 0;
const requestId = response.headers?.['x-request-id'] || response.headers?.['X-Request-Id'] || null;
return [{json:{...context,openai_request_id:requestId,image_usage:usage,image_cost_estimate:cost,api_created_at:api.created || null},binary:{data:{data:base64,mimeType:'image/png',fileName:context.relative_path.split('/').pop(),fileExtension:'png'}}}];
